use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let jobs = input.as_array().unwrap();
    let quantum = input.as_i64().unwrap();
    let mut indices = Vec::new();
    let mut work = 0;
    let mut current_index = 0;

    for job in jobs {
        let work_amount = job.as_i64().unwrap();
        if work_amount <= 0 {
            continue;
        }
        indices.push(current_index);
        work += work_amount;
        if work > quantum {
            indices.push(current_index);
            work = work % quantum;
            current_index += 1;
        }
    }

    indices.sort_unstable();
    Value::Array(indices)
}
